import { ObjectId } from "mongodb";
export function discoveryFixture() {
  const brandA = new ObjectId(),
    brandB = new ObjectId(),
    root = new ObjectId(),
    child = new ObjectId();
  const colour = new ObjectId(),
    memory = new ObjectId(),
    weight = new ObjectId();
  const red = new ObjectId().toString(),
    blue = new ObjectId().toString(),
    small = new ObjectId().toString(),
    large = new ObjectId().toString();
  const products = Array.from({ length: 250 }, (_, i) => ({
    _id: new ObjectId(),
    name: "Fixture Product " + String(i).padStart(3, "0"),
    nameNormalized: "fixture product " + String(i).padStart(3, "0"),
    slug: "fixture-" + i,
    summary: "Fixture",
    modelNumber: "MODEL-" + i,
    tags: ["sample"],
    notes: "PRIVATE-NOTE",
    brandId: i % 2 ? brandA : brandB,
    categoryIds: [root, child],
    primaryCategoryId: child,
    status: i === 0 ? "DRAFT" : i === 1 ? "ARCHIVED" : "ACTIVE",
    thumbnail: { url: "https://example.com/product.webp", alt: "Product" },
    hoverImage: null,
    attributes: [{ attributeId: weight.toString(), value: i }],
    createdAt: new Date(2025, 0, 1 + i),
    publishedAt: new Date(2025, 0, 1 + i),
  }));
  const variants = products.flatMap((p, i) =>
    [0, 1, 2].map((j) => ({
      _id: new ObjectId(),
      productId: p._id,
      sku: "SKU-" + i + "-" + j,
      normalizedSku: "SKU-" + i + "-" + j,
      title: ["Red 8", "Blue 16", "Red 16"][j],
      urlKey: ["red-8", "blue-16", "red-16"][j],
      options: [
        { attributeId: colour.toString(), optionId: j === 1 ? blue : red },
        { attributeId: memory.toString(), optionId: j === 0 ? small : large },
      ],
      active: true,
      archived: false,
      salePaise: [10000, 20000, 30000][j],
      mrpPaise: [15000, 25000, 40000][j],
      priceMode: j === 1 ? "EXCLUSIVE" : "INCLUSIVE",
      gstRateBps: 1800,
      trackQuantity: j !== 2,
      onHand: j === 0 ? 5 : 0,
      reserved: 0,
      stockStatus: "IN_STOCK",
      costPaise: 1234,
      media: [],
    })),
  );
  const option = (id: string, label: string) => ({
    id,
    label,
    colour: "",
    active: true,
  });
  return {
    products,
    variants,
    brandA,
    child,
    red,
    blue,
    small,
    large,
    brands: [brandA, brandB].map((_id, i) => ({
      _id,
      name: "Brand " + i,
      slug: "brand-" + i,
      active: true,
      archivedAt: null,
    })),
    categories: [
      {
        _id: root,
        name: "Parent",
        slug: "parent",
        parentId: null,
        active: true,
        archivedAt: null,
      },
      {
        _id: child,
        name: "Child",
        slug: "child",
        parentId: root,
        active: true,
        archivedAt: null,
      },
    ],
    attributes: [
      {
        _id: colour,
        code: "colour",
        name: "Colour",
        type: "COLOUR",
        options: [option(red, "Red"), option(blue, "Blue")],
        active: true,
        visible: true,
        filterable: true,
      },
      {
        _id: memory,
        code: "memory",
        name: "Memory",
        type: "SINGLE_SELECT",
        options: [option(small, "8"), option(large, "16")],
        active: true,
        visible: true,
        filterable: true,
      },
      {
        _id: weight,
        code: "weight",
        name: "Weight",
        type: "NUMBER",
        unit: "g",
        options: [],
        active: true,
        visible: true,
        filterable: true,
      },
    ],
  };
}
